type BusinessRules = {
  stageProb: Record<string, number>;
  avgDaysPerStage: Record<string, number>;
  saraThresholds: Record<string, SaraThreshold>;
  legalPhaseThresholds: Record<string, LegalPhaseThreshold>;
  cierrePlazos: CierrePlazos;
};
const DEFAULT_BUSINESS_RULES: BusinessRules = {
  stageProb: {
    'Contacto Inicial': 0.05, 'Calificación': 0.15, 'Presentación': 0.30,
    'Negociación': 0.60, 'Cierre': 0.85, 'Post-venta': 1.0, 'Lead Frío': 0.02,
  },
  avgDaysPerStage: {
    'Contacto Inicial': 14, 'Calificación': 21, 'Presentación': 30,
    'Negociación': 45, 'Cierre': 20, 'Lead Frío': 60,
  },
  // Ciclo de venta inmobiliaria HNWI cross-border es lento por naturaleza (semanas, no
  // días) — los umbrales previos (ej. 10 días sin contacto = crítico en Contacto Inicial)
  // marcaban casi todo el embudo en rojo con actividad de seguimiento normal.
  saraThresholds: {
    'Contacto Inicial': { tibio: 5, frio: 12, critico: 21 },
    'Calificación':     { tibio: 7, frio: 14, critico: 25 },
    'Presentación':     { tibio: 7, frio: 15, critico: 25 },
    'Negociación':      { tibio: 4, frio: 8,  critico: 15 },
    'Cierre':           { tibio: 2, frio: 4,  critico: 8 },
    'Post-venta':       { tibio: 14, frio: 30, critico: 60 },
  },
  // Días sin actividad dentro de la fase legal antes de marcarla ámbar/roja en el panel
  // de Legal & Cierre — cada fase tiene su propio ritmo natural (Reserva se resuelve en
  // días, Promesa y Escritura toman semanas por trámites notariales/registrales).
  legalPhaseThresholds: {
    reserva:   { amber: 5,  red: 10 },
    promesa:   { amber: 15, red: 30 },
    escritura: { amber: 20, red: 40 },
  },
  // Plazos por defecto al generar el expediente de Cierre desde Legal (ver
  // triggerCierreAutomation). Antes estaban fijos en el código (3/30/150/180 días) —
  // ahora son ajustables aquí porque escritura y entrega dependen del avance real de obra
  // de cada proyecto, no de un número fijo de días desde la separación. Cuando el proyecto
  // tiene unidades con fecha de entrega estimada cargada en el inventario (Catálogo →
  // Unidades → "fecha lista"), esa fecha real prima sobre este plazo por defecto.
  cierrePlazos: { reservaDias: 3, promesaDias: 30, escrituraDias: 150, entregaDias: 180 },
};

